import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.sX5ch2UU.js";const u=JSON.parse('{"title":"Contributing","description":"How to contribute to Nette API and to this documentation: running the tests and example e2e checks, editing diagrams, and previewing the docs locally.","frontmatter":{"title":"Contributing","description":"How to contribute to Nette API and to this documentation: running the tests and example e2e checks, editing diagrams, and previewing the docs locally."},"headers":[],"relativePath":"contributing.md","filePath":"contributing.md","lastUpdated":1793309165000}'),n={name:"contributing.md"};function o(r,e,l,h,d,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h1><p>Contributions are <strong>welcome</strong> and will be fully <strong>credited</strong>.</p><p>We accept contributions via Pull Requests on <a href="https://github.com/tomaj/nette-api" target="_blank" rel="noreferrer">Github</a>.</p><h2 id="pull-requests" tabindex="-1">Pull Requests <a class="header-anchor" href="#pull-requests" aria-label="Permalink to &quot;Pull Requests&quot;">​</a></h2><ul><li><p><strong><a href="https://github.com/php-fig/fig-standards/blob/master/accepted/PSR-2-coding-style-guide.md" target="_blank" rel="noreferrer">PSR-2 Coding Standard</a></strong> - The easiest way to apply the conventions is to install <a href="http://pear.php.net/package/PHP_CodeSniffer" target="_blank" rel="noreferrer">PHP Code Sniffer</a>.</p></li><li><p><strong>Add tests!</strong> - Your patch won&#39;t be accepted if it doesn&#39;t have tests.</p></li><li><p><strong>Document any change in behaviour</strong> - Make sure the <code>README.md</code> and any other relevant documentation are kept up-to-date.</p></li><li><p><strong>Consider our release cycle</strong> - We try to follow <a href="http://semver.org/" target="_blank" rel="noreferrer">SemVer v2.0.0</a>. Randomly breaking public APIs is not an option.</p></li><li><p><strong>Create feature branches</strong> - Don&#39;t ask us to pull from your master branch.</p></li><li><p><strong>One pull request per feature</strong> - If you want to do more than one thing, send multiple pull requests.</p></li><li><p><strong>Send coherent history</strong> - Make sure each individual commit in your pull request is meaningful. If you had to make multiple intermediate commits while developing, please <a href="http://www.git-scm.com/book/en/v2/Git-Tools-Rewriting-History#Changing-Multiple-Commit-Messages" target="_blank" rel="noreferrer">squash them</a> before submitting.</p></li></ul><h2 id="running-tests" tabindex="-1">Running Tests <a class="header-anchor" href="#running-tests" aria-label="Permalink to &quot;Running Tests&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>Coverage reports (<code>build/logs/clover.xml</code>, <code>build/coverage/</code>) are opt-in and need Xdebug:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> coverage</span></span></code></pre></div><p><strong>Happy coding</strong>!</p><h2 id="this-documentation" tabindex="-1">This documentation <a class="header-anchor" href="#this-documentation" aria-label="Permalink to &quot;This documentation&quot;">​</a></h2><p>The site is in <code>docs/</code>, built with VitePress, Node 22:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # http://localhost:5173/nette-api/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:links</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # check links in the built site</span></span></code></pre></div><ul><li>Code on the example pages comes from the projects in <code>examples/</code> through <code>&lt;&lt;&lt; @/../examples/...</code>; change the project, not the page. Each project has an <code>e2e.sh</code> that CI runs.</li><li>Every English page has a Slovak twin under <code>docs/sk/</code>; <code>npm run check</code> fails when one is missing.</li><li>Diagrams are Excalidraw files in <code>docs/diagrams/</code>, rendered to light and dark SVG with <code>npm run diagrams</code>.</li><li>Every pull request gets a preview at <code>https://tomaj.github.io/nette-api/pr-preview/pr-&lt;number&gt;/</code>.</li></ul><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><h3 id="how-do-i-run-the-tests" tabindex="-1">How do I run the tests? <a class="header-anchor" href="#how-do-i-run-the-tests" aria-label="Permalink to &quot;How do I run the tests?&quot;">​</a></h3><p><code>composer test</code> runs PHPUnit. <code>composer coverage</code> also writes coverage reports to <code>build/</code> (needs Xdebug). Each example project also has an <code>e2e.sh</code>, see <a href="/nette-api/pr-preview/pr-225/examples/">Examples</a>.</p><h3 id="do-i-have-to-update-the-documentation-with-my-change" tabindex="-1">Do I have to update the documentation with my change? <a class="header-anchor" href="#do-i-have-to-update-the-documentation-with-my-change" aria-label="Permalink to &quot;Do I have to update the documentation with my change?&quot;">​</a></h3><p>Yes, a change in behaviour needs the docs updated, in English and Slovak.</p><h3 id="how-do-i-see-my-documentation-change-before-it-is-merged" tabindex="-1">How do I see my documentation change before it is merged? <a class="header-anchor" href="#how-do-i-see-my-documentation-change-before-it-is-merged" aria-label="Permalink to &quot;How do I see my documentation change before it is merged?&quot;">​</a></h3><p>Run <code>npm run docs:dev</code> in <code>docs/</code>, or open the preview that every pull request gets.</p>`,21)])])}const g=t(n,[["render",o]]);export{u as __pageData,g as default};
